<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require (dirname(__DIR__, 2) . '/app/Bootstrap/bootstrap.php');MarketplaceModule::boot();require_once (dirname(__DIR__, 2) . '/app/Modules/Marketplace/Integrations/TikTokShop/TikTokDataClient.php');
$_SESSION=['company_key'=>'LOCAL-COMPANY','role'=>'OWNER','user_id'=>'READ-LABEL-CHECK','workspace'=>'marketplace'];$p=Database::pdo();
$q=$p->prepare("SELECT c.*,s.store_name FROM marketplace_oauth_connections c JOIN marketplace_stores s ON s.id=c.store_id AND s.company_key=c.company_key WHERE c.company_key=? AND s.archived_at IS NULL AND c.status='verified'");$q->execute([(new MarketplaceScopeService($p))->companyKey()]);
foreach($q->fetchAll(PDO::FETCH_ASSOC) as $c){$result=['platform'=>$c['platform'],'store'=>$c['store_name'],'verified'=>true,'token_expired'=>!empty($c['token_expires_at'])&&strtotime($c['token_expires_at'])<time()];$scopes=json_decode((string)$c['granted_scopes'],true);$result['fulfillment_scope_recorded']=is_array($scopes)?array_values(array_filter($scopes,fn($s)=>is_string($s)&&str_contains(strtolower($s),'fulfillment'))):[];
