while($row=$st->fetch(PDO::FETCH_ASSOC)){$raw=json_decode($row['payload_json'],true)?:[];$packages=$raw['packages']??[];foreach($raw['line_items']??[] as $line)if(!empty($line['package_id']))$packages[]=['id'=>$line['package_id']];foreach($packages as $package){$id=(string)($package['id']??$package['package_id']??'');if($id!==''&&!isset($candidates[$id]))$candidates[$id]=['status'=>$raw['status']??'UNKNOWN','tracking_present'=>!empty($raw['tracking_number'])];}if(count($candidates)>=2)break;}
